                      )),
                  const SizedBox(height: 8),
                  const Divider(height: 1, color: _border),
                  const SizedBox(height: 8),
                  _DetailRow(label: 'Net Pay',
                      value: widget.money.format(e.net),
                      color: _green, bold: true),
                  if (e.disbursedAt != null) ...[
                    const SizedBox(height: 8),
