}

// ── Payroll Card (from payrolls collection — HR-generated) ────────────────────
class _PayrollCard extends StatefulWidget {
  final _SalaryEntry entry;
  final NumberFormat money;
  final String Function(dynamic) formatDate;

  const _PayrollCard({
    required this.entry,
    required this.money,
    required this.formatDate,
  });

  @override
  State<_PayrollCard> createState() => _PayrollCardState();
}

class _PayrollCardState extends State<_PayrollCard> {
  bool _expanded = false;

  @override
  Widget build(BuildContext context) {
    final e = widget.entry;

    Color statusColor;
    String statusLabel;
    IconData statusIcon;
    switch (e.status) {
      case 'disbursed':
        statusColor = _green;
        statusLabel = 'Paid';
        statusIcon  = Icons.check_circle_rounded;
        break;
      case 'requested':
        statusColor = _orange;
        statusLabel = 'Processing';
        statusIcon  = Icons.hourglass_top_rounded;
        break;
      default:
        statusColor = _muted;
        statusLabel = 'Pending';
        statusIcon  = Icons.schedule_rounded;
    }

    return Container(
      margin: const EdgeInsets.only(bottom: 12),
      decoration: BoxDecoration(
        color: _card,
        borderRadius: BorderRadius.circular(14),
        border: Border.all(
          color: e.status == 'disbursed'
              ? _green.withValues(alpha: 0.2)
              : _border,
        ),
        boxShadow: const [
          BoxShadow(color: Color(0x06000000), blurRadius: 6, offset: Offset(0, 2)),
        ],
      ),
      child: Column(
        children: [
          // Header row
          Padding(
            padding: const EdgeInsets.fromLTRB(14, 14, 14, 0),
            child: Row(children: [
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(e.period,
                        style: GoogleFonts.inter(
                            fontWeight: FontWeight.w800,
                            fontSize: 15, color: _fg)),
                    const SizedBox(height: 2),
                    Text(
                      'Generated ${widget.formatDate(e.generatedAt)}',
                      style: GoogleFonts.inter(
                          color: _muted, fontSize: 11),
                    ),
                  ],
                ),
              ),
              // Net amount
              Column(
                crossAxisAlignment: CrossAxisAlignment.end,
                children: [
                  Text(widget.money.format(e.net),
                      style: GoogleFonts.inter(
                          fontWeight: FontWeight.w800,
                          fontSize: 16,
                          color: e.status == 'disbursed' ? _green : _fg)),
                  const SizedBox(height: 4),
                  Container(
                    padding: const EdgeInsets.symmetric(
                        horizontal: 8, vertical: 3),
                    decoration: BoxDecoration(
                      color: statusColor.withValues(alpha: 0.1),
                      borderRadius: BorderRadius.circular(99),
                      border: Border.all(
                          color: statusColor.withValues(alpha: 0.3)),
                    ),
                    child: Row(mainAxisSize: MainAxisSize.min, children: [
                      Icon(statusIcon, size: 10, color: statusColor),
                      const SizedBox(width: 3),
                      Text(statusLabel,
                          style: GoogleFonts.inter(
                              fontSize: 10,
                              fontWeight: FontWeight.w700,
                              color: statusColor)),
                    ]),
                  ),
                ],
              ),
            ]),
          ),

          const SizedBox(height: 10),

          // Breakdown row
          Container(
            margin: const EdgeInsets.symmetric(horizontal: 14),
            padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
            decoration: BoxDecoration(
              color: _bg,
              borderRadius: BorderRadius.circular(10),
            ),
            child: Row(children: [
              _SummaryCell(label: 'GROSS',
                  value: widget.money.format(e.gross), color: _fg),
              _SummaryCell(
                  label: 'BONUS',
                  value: e.bonus > 0
                      ? '+${widget.money.format(e.bonus)}'
                      : '৳0',
                  color: e.bonus > 0 ? _green : _muted),
              _SummaryCell(
                  label: 'DEDUCTION',
                  value: e.loan > 0
                      ? '-${widget.money.format(e.loan)}'
                      : '৳0',
                  color: e.loan > 0 ? _red : _muted),
            ]),
          ),

          // Expand toggle
          InkWell(
            onTap: () => setState(() => _expanded = !_expanded),
            borderRadius: const BorderRadius.vertical(
                bottom: Radius.circular(14)),
            child: Padding(
              padding: const EdgeInsets.symmetric(
                  horizontal: 14, vertical: 10),
              child: Row(children: [
                Text(_expanded ? 'Hide details' : 'View details',
                    style: GoogleFonts.inter(
                        color: _blue,
                        fontWeight: FontWeight.w600,
                        fontSize: 12)),
                const SizedBox(width: 4),
                Icon(
                  _expanded
                      ? Icons.keyboard_arrow_up_rounded
                      : Icons.keyboard_arrow_down_rounded,
                  color: _blue, size: 16,
                ),
              ]),
            ),
          ),

          if (_expanded) ...[
            const Divider(height: 1, color: _border),
            Padding(
              padding: const EdgeInsets.fromLTRB(14, 12, 14, 14),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  _DetailRow(label: 'Base Salary',
                      value: widget.money.format(e.gross), color: _fg),
                  if (e.bonus > 0)
                    _DetailRow(label: 'Bonus',
                        value: '+${widget.money.format(e.bonus)}',
                        color: _green),
                  if (e.loan > 0)
                    _DetailRow(label: 'Loan Deduction',
                        value: '-${widget.money.format(e.loan)}',
                        color: _red),
                  ...e.extras.map((ex) => _DetailRow(
                        label: (ex['label'] ?? 'Deduction').toString(),
                        value: '-${widget.money.format(
                            double.tryParse(ex['amount']?.toString() ?? '0') ?? 0)}',
                        color: _orange,
                      )),
                  const SizedBox(height: 8),
                  const Divider(height: 1, color: _border),
                  const SizedBox(height: 8),
                  _DetailRow(label: 'Net Pay',
                      value: widget.money.format(e.net),
                      color: _green, bold: true),
                  if (e.status == 'disbursed' && e.disbursedAt != null) ...[
                    const SizedBox(height: 6),
                    Row(children: [
                      const Icon(Icons.check_circle_rounded,
                          size: 12, color: _green),
                      const SizedBox(width: 4),
                      Text(
                        'Paid on ${widget.formatDate(e.disbursedAt)}'
                        '${e.method.isNotEmpty ? ' via ${e.method}' : ''}',
                        style: GoogleFonts.inter(
                            color: _green, fontSize: 11,
                            fontWeight: FontWeight.w600),
                      ),
                    ]),
                  ],
                ],
              ),
            ),
          ],
        ],
      ),
    );
  }
}

// ── Shared widgets ────────────────────────────────────────────────────────────
class _SummaryCell extends StatelessWidget {
  final String label, value;
  final Color color;
  const _SummaryCell(
      {required this.label, required this.value, required this.color});

  @override
  Widget build(BuildContext context) {
    return Expanded(
      child: Column(children: [
        Text(label,
            style: GoogleFonts.inter(
                color: _muted, fontSize: 9,
                fontWeight: FontWeight.w700, letterSpacing: 0.5)),
        const SizedBox(height: 3),
        FittedBox(
          child: Text(value,
              style: GoogleFonts.inter(
                  fontWeight: FontWeight.w700, fontSize: 13, color: color)),
        ),
      ]),
    );
  }
}

class _DetailRow extends StatelessWidget {
  final String label, value;
  final Color color;
  final bool bold;
  const _DetailRow({
    required this.label,
    required this.value,
    required this.color,
    this.bold = false,
  });

  @override
  Widget build(BuildContext context) {
    return Padding(
      padding: const EdgeInsets.only(bottom: 8),
      child: Row(
        mainAxisAlignment: MainAxisAlignment.spaceBetween,
        children: [
          Text(label,
              style: GoogleFonts.inter(
                  color: bold ? _fg : _muted,
                  fontSize: 13,
                  fontWeight: bold ? FontWeight.w700 : FontWeight.w500)),
          Text(value,
              style: GoogleFonts.inter(
                  color: color, fontSize: 13,
                  fontWeight: bold ? FontWeight.w800 : FontWeight.w700)),
        ],
      ),
    );
  }
}

class _EmptyState extends StatelessWidget {
  final IconData icon;
  final String title, subtitle;
  const _EmptyState(
      {required this.icon, required this.title, required this.subtitle});

  @override
  Widget build(BuildContext context) {
    return Center(
      child: Padding(
        padding: const EdgeInsets.all(32),
        child: Column(mainAxisSize: MainAxisSize.min, children: [
          Container(
            width: 72, height: 72,
            decoration: BoxDecoration(
              color: _green.withValues(alpha: 0.08),
              borderRadius: BorderRadius.circular(20),
            ),
            child: Icon(icon, size: 34, color: _green),
          ),
          const SizedBox(height: 16),
          Text(title,
              style: GoogleFonts.inter(
                  fontWeight: FontWeight.w800, fontSize: 16, color: _fg)),
          const SizedBox(height: 6),
          Text(subtitle,
              textAlign: TextAlign.center,
              style: GoogleFonts.inter(color: _muted, fontSize: 13, height: 1.5)),
        ]),
      ),
    );
  }
}

class _ErrorView extends StatelessWidget {
  final String message;
  const _ErrorView({required this.message});

  @override
  Widget build(BuildContext context) {
    return Center(
      child: Padding(
        padding: const EdgeInsets.all(32),
        child: Column(mainAxisSize: MainAxisSize.min, children: [
          const Icon(Icons.error_outline_rounded, size: 40, color: _red),
          const SizedBox(height: 12),
          Text('Could not load salary data',
              style: GoogleFonts.inter(
                  fontWeight: FontWeight.w700, fontSize: 15, color: _fg)),
          const SizedBox(height: 6),
          Text(message,
              textAlign: TextAlign.center,
              style: GoogleFonts.inter(color: _muted, fontSize: 12)),
        ]),
      ),
    );
  }
}
